import * as THREE from 'three';
import type { Vec3 } from '../contracts/math';
import { RotatingObstacle, type RotatingObstacleOptions } from './RotatingObstacle';
import type { ObstacleColliderSpec } from './types';
import { requirePositive } from './validation';

export interface RotatingBarOptions extends RotatingObstacleOptions {
  length?: number;
  thickness?: number;
  height?: number;
  color?: number;
}

export class RotatingBar extends RotatingObstacle {
  readonly length: number;
  readonly thickness: number;
  readonly height: number;
  readonly colliders: readonly ObstacleColliderSpec[];

  constructor(options: RotatingBarOptions) {
    super(options);
    this.length = requirePositive(options.length ?? 4, 'bar length');
    this.thickness = requirePositive(options.thickness ?? 0.35, 'bar thickness');
    this.height = requirePositive(options.height ?? 0.45, 'bar height');

    const geometry = new THREE.BoxGeometry(this.length, this.height, this.thickness);
    const material = new THREE.MeshStandardMaterial({ color: options.color ?? 0xe4572e });
    const mesh = new THREE.Mesh(geometry, material);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.pivot.add(mesh);

    this.colliders = [{
      halfExtents: { x: this.length / 2, y: this.height / 2, z: this.thickness / 2 },
      offset: { x: 0, y: 0, z: 0 },
    }];
    this.mountBody(this.colliders);
  }
}
EOF

