import * as THREE from 'three';
import { RotatingObstacle, type RotatingObstacleOptions } from './RotatingObstacle';
import type { ObstacleColliderSpec } from './types';
import { TAU } from './rotation';
import { requireCount, requirePositive } from './validation';

export interface SpinnerOptions extends RotatingObstacleOptions {
  armCount?: number;
  armLength?: number;
  thickness?: number;
  height?: number;
  hubRadius?: number;
  color?: number;
}

export class Spinner extends RotatingObstacle {
  readonly armCount: number;
  readonly armLength: number;
  readonly thickness: number;
  readonly height: number;
  readonly hubRadius: number;
  readonly colliders: readonly ObstacleColliderSpec[];

  constructor(options: SpinnerOptions) {
    super(options);
    this.armCount = requireCount(options.armCount ?? 4, 'spinner arm count', 2);
    this.armLength = requirePositive(options.armLength ?? 2.5, 'spinner arm length');
    this.thickness = requirePositive(options.thickness ?? 0.3, 'spinner thickness');
    this.height = requirePositive(options.height ?? 0.4, 'spinner height');
    this.hubRadius = requirePositive(options.hubRadius ?? 0.35, 'spinner hub radius');

    const material = new THREE.MeshStandardMaterial({ color: options.color ?? 0x00b8a9 });
    const colliders: ObstacleColliderSpec[] = [];

    for (let index = 0; index < this.armCount; index += 1) {
      const angle = (TAU * index) / this.armCount;
      const arm = new THREE.Mesh(
        new THREE.BoxGeometry(this.armLength, this.height, this.thickness),
        material,
      );
      arm.position.set(Math.cos(angle) * this.armLength / 2, 0, -Math.sin(angle) * this.armLength / 2);
      arm.rotation.y = angle;
      arm.castShadow = true;
      arm.receiveShadow = true;
      this.pivot.add(arm);

      colliders.push({
        halfExtents: { x: this.armLength / 2, y: this.height / 2, z: this.thickness / 2 },
        offset: {
          x: Math.cos(angle) * this.armLength / 2,
          y: 0,
          z: -Math.sin(angle) * this.armLength / 2,
        },
        rotation: { x: 0, y: Math.sin(angle / 2), z: 0, w: Math.cos(angle / 2) },
      });
    }

    const hub = new THREE.Mesh(
      new THREE.CylinderGeometry(this.hubRadius, this.hubRadius, this.height * 1.2, 20),
      material,
    );
    hub.castShadow = true;
    hub.receiveShadow = true;
    this.pivot.add(hub);

    this.colliders = colliders;
    this.mountBody(this.colliders);
  }
}
EOF

